$fitmatch$::jsonb) as x(
  source text,
  product_id text,
  product_name text,
  source_category_path text,
  expected_category text,
  expected_detail text,
  expected_family text,
  expected_length text,
  expected_confirmation boolean,
  verdict text,
  confidence text,
  basis text
);

do $$
declare
  v_rows integer;
  v_distinct integer;
  v_release_rows integer;
  v_target_rows integer;
begin
  select count(*), count(distinct source || '|' || product_id)
    into v_rows, v_distinct
  from tmp_fitmatch_adjudication;

  if v_rows <> 207 or v_distinct <> 207 then
    raise exception 'adjudication payload must contain 207 unique products; rows=%, distinct=%',
      v_rows, v_distinct;
  end if;

  select count(*) into v_release_rows
  from fitmatch_qa.classification_cases
  where release_id = '568c3153-a45e-4d4e-b9a7-59c2179733be'::uuid;

  if v_release_rows <> 5026 then
    raise exception 'unexpected QA release size: expected 5026, got %', v_release_rows;
  end if;

  select count(*) into v_target_rows
  from fitmatch_qa.classification_cases c
  join tmp_fitmatch_adjudication a
    on a.source = c.source and a.product_id = c.product_id
  where c.release_id = '568c3153-a45e-4d4e-b9a7-59c2179733be'::uuid;

  if v_target_rows <> 207 then
    raise exception 'all 207 adjudicated products must exist in the QA release; found %', v_target_rows;
  end if;
end $$;

update fitmatch_qa.classification_cases c
set requires_user_confirmation = a.expected_confirmation,
    expected_category_code = a.expected_category,
    expected_detail_code = a.expected_detail,
    expected_comparison_family = a.expected_family,
    expected_length_type = a.expected_length,
    result_payload = c.result_payload || jsonb_build_object(
      'finalCategoryCode', a.expected_category,
      'finalDetailCode', a.expected_detail,
      'garmentFamily', a.expected_family,
      'lengthType', a.expected_length,
      'classificationIsValid', not a.expected_confirmation,
      'userConfirmationRequired', a.expected_confirmation,
      'adjudicationVerdict', a.verdict,
      'adjudicationConfidence', a.confidence,
      'adjudicationBasis', a.basis,
      'adjudicatedAt', '2026-08-16'
    )
from tmp_fitmatch_adjudication a
where c.release_id = '568c3153-a45e-4d4e-b9a7-59c2179733be'::uuid
  and c.source = a.source
  and c.product_id = a.product_id;

do $$
declare
  v_exact integer;
begin
  select count(*) into v_exact
  from fitmatch_qa.classification_cases c
  join tmp_fitmatch_adjudication a
    on a.source = c.source and a.product_id = c.product_id
  where c.release_id = '568c3153-a45e-4d4e-b9a7-59c2179733be'::uuid
    and c.requires_user_confirmation is not distinct from a.expected_confirmation
    and c.expected_category_code is not distinct from a.expected_category
    and c.expected_detail_code is not distinct from a.expected_detail
    and c.expected_comparison_family is not distinct from a.expected_family
    and c.expected_length_type is not distinct from a.expected_length;

  if v_exact <> 207 then
    raise exception 'postcondition failed: expected 207 aligned QA rows, got %', v_exact;
  end if;
end $$;

commit;

select
  count(*) as total_cases,
  count(*) filter (where requires_user_confirmation) as confirmation_required,
  count(*) filter (where not requires_user_confirmation) as auto_classified
from fitmatch_qa.classification_cases
where release_id = '568c3153-a45e-4d4e-b9a7-59c2179733be'::uuid;

select source, product_id, product_name,
       expected_category_code, expected_detail_code,
       expected_comparison_family, expected_length_type,
       requires_user_confirmation
from fitmatch_qa.classification_cases
where release_id = '568c3153-a45e-4d4e-b9a7-59c2179733be'::uuid
  and source = 'uniqlo' and product_id = 'E492123';

